-- =============================================================================
-- Seed: Módulo de Cata — datos de prueba
-- Requiere: auth_seed.sql y edicion_seed.sql aplicados primero
-- Idempotente: usa INSERT ... ON CONFLICT DO NOTHING
--
-- Constantes de referencia:
--   edicion_id: dddddddd-0000-0000-0000-000000000001
--   org_id:     bbbbbbbb-0000-0000-0000-000000000001
--   judge base: cccccccc-0000-0000-0000-000000000002 (judge@copa.com)
--   brewery:    cccccccc-0000-0000-0000-000000000003 (brewery@copa.com)
-- =============================================================================

-- La edición debe estar en estado 'cata' para que el módulo de cata tenga
-- sentido (endpoints de juez/admin de cata filtran por estado in ('cata', 'pre-cata')).
UPDATE ediciones SET estado = 'cata' WHERE id = 'dddddddd-0000-0000-0000-000000000001';

